=== FILE: rr_arbiter.v ===
// rr_arbiter.v - round-robin arbiter for N requesters (default 4).
// Requirement: req-142be1ce31 (round-robin arbiter for four requesters).
// Interface:   interface_spec.md. Plan: microarchitecture.md.
//
// State: one priority pointer, ptr, $clog2(N) bits, reset to 0.
// grant is a combinational function of req and ptr: the first requester
// with req high at or after ptr, searching upwards and wrapping from N-1
// to 0 (wrap by comparison with LAST, so N need not be a power of two).
// On a rising edge with a grant, ptr moves to one past the winner.
// With no request, ptr holds. rst_n is synchronous and active low; grant
// is not gated by reset.

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer  PW    = (N > 1) ? $clog2(N) : 1;
    localparam integer  LAST  = N - 1;
    localparam [N-1:0]  ONE_N = {{(N-1){1'b0}}, 1'b1};
    localparam [PW-1:0] ONE_P = {PW{1'b1}} >> (PW - 1);

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_nxt;

    // Search temporaries: every one is assigned before it is read.
    integer      s_k;
    integer      s_idx;
    reg [PW-1:0] s_cand;
    reg          s_found;
    reg [N-1:0]  s_req_sh;

    // Wrapping priority search from ptr (microarchitecture section 2).
    // s_idx (integer) and s_cand (PW bits) always name the same requester:
    // s_idx is used for the comparison with LAST, s_cand for the selection
    // and the next pointer value.
    always @* begin
        s_idx  = {{(32-PW){1'b0}}, ptr};
        s_cand = ptr;
        if (s_idx > LAST) begin
            // Unreachable from reset; keeps the search in range.
            s_idx  = 0;
            s_cand = {PW{1'b0}};
        end
        grant    = {N{1'b0}};
        ptr_nxt  = s_cand;
        s_found  = 1'b0;
        s_req_sh = {N{1'b0}};
        for (s_k = 0; s_k < N; s_k = s_k + 1) begin
            s_req_sh = req >> s_cand;
            if (!s_found && s_req_sh[0]) begin
                s_found = 1'b1;
                grant   = ONE_N << s_cand;
                ptr_nxt = (s_idx == LAST) ? {PW{1'b0}} : (s_cand + ONE_P);
            end
            if (s_idx == LAST) begin
                s_idx  = 0;
                s_cand = {PW{1'b0}};
            end else begin
                s_idx  = s_idx + 1;
                s_cand = s_cand + ONE_P;
            end
        end
    end

    // Pointer register (microarchitecture sections 3 and 4).
    always @(posedge clk) begin
        if (!rst_n) begin
            ptr <= {PW{1'b0}};
        end else begin
            ptr <= ptr_nxt;
        end
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec.md section 6). Read with
    // `read -formal`. No proof setup is delivered with this file.
    reg        f_past_valid;
    reg [31:0] f_ptr;
    reg [31:0] f_win;
    reg [31:0] f_wdist;
    reg [31:0] f_exp_ptr;
    integer    f_k;

    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) begin
        if (!f_past_valid) assume (!rst_n);
    end

    always @(*) begin
        f_ptr = {{(32-PW){1'b0}}, ptr};
        f_win = 32'd0;
        for (f_k = 0; f_k < N; f_k = f_k + 1)
            if (grant[f_k]) f_win = f_k;
        f_wdist = (f_win >= f_ptr) ? (f_win - f_ptr) : (f_win + N - f_ptr);
    end

    // Reference next-pointer model.
    always @(posedge clk) begin
        if (!rst_n)
            f_exp_ptr <= 32'd0;
        else if (grant != {N{1'b0}})
            f_exp_ptr <= (f_win == LAST) ? 32'd0 : (f_win + 32'd1);
        else
            f_exp_ptr <= f_ptr;
    end

    always @(*) begin
        if (f_past_valid) begin
            assert (f_ptr <= LAST);
            assert (f_ptr == f_exp_ptr);
            assert ((grant & (grant - ONE_N)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            if (req != {N{1'b0}}) assert (grant != {N{1'b0}});
            if (rst_n) cover (req == {N{1'b1}});
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n)) assert (ptr == {PW{1'b0}});
        if (f_past_valid && $past(rst_n) && rst_n)
            cover (($past(f_ptr) == LAST) && (f_ptr == 32'd0));
    end

    genvar f_gi;
    generate
        for (f_gi = 0; f_gi < N; f_gi = f_gi + 1) begin : g_fair
            wire [31:0] f_idx  = f_gi;
            wire [31:0] f_dist = (f_idx >= f_ptr) ? (f_idx - f_ptr)
                                                  : (f_idx + N - f_ptr);
            reg  [31:0] f_wait;
            always @(posedge clk) begin
                if (!rst_n || !req[f_gi] || grant[f_gi])
                    f_wait <= 32'd0;
                else
                    f_wait <= f_wait + 32'd1;
            end
            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= LAST);
                    assert ((f_wait + f_dist) <= LAST);
                    if ((grant != {N{1'b0}}) && (f_dist < f_wdist))
                        assert (!req[f_gi]);
                    if (rst_n) cover (grant[f_gi]);
                    if (rst_n) cover (f_wait == LAST);
                end
            end
        end
    endgenerate
`endif

endmodule
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// rr_arbiter_tb.v - self-checking testbench for rr_arbiter at N 4 and N 5.
// Requirement: req-142be1ce31. Checks interface_spec.md section 6.
// Every cycle: grant against a reference pointer model, and per-requester
// wait counters against the N-1 bound. Coverage counters fail the run if a
// required case was not reached.

module rr_arbiter_tb;

    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) dut4 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req4),
        .grant (grant4)
    );

    rr_arbiter #(.N(5)) dut5 (
        .clk   (clk),
        .rst_n (rst_n),
        .req   (req5),
        .grant (grant5)
    );

    reg [8*64-1:0] nonce;
    integer        passed;
    integer        failed;

    // Reference model and check state, index 0 for N 4 and 1 for N 5.
    integer        m_ptr     [0:1];
    integer        m_win     [0:1];
    integer        waitc     [0:15];
    integer        cov_none  [0:1];
    integer        cov_all   [0:1];
    integer        cov_held  [0:1];
    integer        cov_maxw  [0:1];
    integer        cov_rst   [0:1];
    reg     [7:0]  cov_alone [0:1];
    reg     [7:0]  prev_r    [0:1];
    reg     [7:0]  last_g    [0:1];
    reg            rs;
    reg            prev_rs;
    reg            ptr_valid;
    integer        k;
    integer        q;
    reg     [31:0] rnd;

    initial begin
        clk = 1'b0;
        forever #5 clk = ~clk;
    end

    // First requester with r high at or after p, wrapping at n; -1 if none.
    function integer rr_winner;
        input [7:0]   r;
        input integer p;
        input integer n;
        integer       kk;
        integer       idx;
        integer       w;
        reg   [7:0]   sh;
        begin
            w = -1;
            for (kk = 0; kk < n; kk = kk + 1) begin
                idx = p + kk;
                if (idx >= n) idx = idx - n;
                sh = r >> idx;
                if ((w < 0) && sh[0]) w = idx;
            end
            rr_winner = w;
        end
    endfunction

    function [7:0] onehot8;
        input integer w;
        begin
            onehot8 = (w >= 0) ? (8'd1 << w) : 8'd0;
        end
    endfunction

    function [7:0] mask8;
        input integer n;
        begin
            mask8 = (8'd1 << n) - 8'd1;
        end
    endfunction

    // Check one arbiter's outputs for the current cycle (before the edge).
    task check_dut;
        input integer dd;
        input [7:0]   r;
        input [7:0]   g;
        input integer n;
        integer       j;
        integer       w;
        integer       viol;
        reg   [7:0]   e;
        reg   [7:0]   rb;
        reg   [7:0]   gb;
        reg   [7:0]   others;
        begin
            w = rr_winner(r, m_ptr[dd], n);
            e = onehot8(w);
            m_win[dd]  = w;
            last_g[dd] = g;
            if (ptr_valid) begin
                if (g !== e) begin
                    $error("rr_arbiter N=%0d: grant %b, expected %b (req %b, model pointer %0d)",
                           n, g, e, r, m_ptr[dd]);
                    failed = failed + 1;
                end else begin
                    passed = passed + 1;
                end
                viol = 0;
                for (j = 0; j < n; j = j + 1) begin
                    rb     = r >> j;
                    gb     = g >> j;
                    others = (r ^ prev_r[dd]) & ~onehot8(j);
                    if (rs && prev_rs && rb[0] && (waitc[dd*8+j] > 0) && (others != 8'd0))
                        cov_held[dd] = 1;
                    if (!rs) begin
                        waitc[dd*8+j] = 0;
                    end else if (rb[0] && !gb[0]) begin
                        waitc[dd*8+j] = waitc[dd*8+j] + 1;
                        if (waitc[dd*8+j] == n - 1) cov_maxw[dd] = 1;
                        if (waitc[dd*8+j] > n - 1) begin
                            $error("rr_arbiter N=%0d: requester %0d held its request %0d cycles without a grant",
                                   n, j, waitc[dd*8+j]);
                            failed = failed + 1;
                            viol   = 1;
                        end
                    end else begin
                        waitc[dd*8+j] = 0;
                    end
                end
                if (viol == 0) passed = passed + 1;
                if (rs) begin
                    if (r == 8'd0) cov_none[dd] = 1;
                    if (r == mask8(n)) cov_all[dd] = 1;
                    if ((r != 8'd0) && ((r & (r - 8'd1)) == 8'd0))
                        cov_alone[dd] = cov_alone[dd] | r;
                end else if (r != 8'd0) begin
                    cov_rst[dd] = 1;
                end
            end
            prev_r[dd] = r;
        end
    endtask

    // Move the reference pointer on the rising edge.
    task advance_dut;
        input integer dd;
        input integer n;
        begin
            if (!rs)
                m_ptr[dd] = 0;
            else if (m_win[dd] >= 0)
                m_ptr[dd] = (m_win[dd] == n - 1) ? 0 : m_win[dd] + 1;
        end
    endtask

    // Inputs are set just after a falling edge; sample, then take the edge.
    task run_cycle;
        begin
            #1;
            rs = rst_n;
            check_dut(0, {4'b0000, req4}, {4'b0000, grant4}, 4);
            check_dut(1, {3'b000, req5}, {3'b000, grant5}, 5);
            prev_rs = rs;
            @(posedge clk);
            advance_dut(0, 4);
            advance_dut(1, 5);
            if (!rs) ptr_valid = 1'b1;
            @(negedge clk);
        end
    endtask

    task cov_check;
        input integer ok;
        input integer n;
        input integer what;
        begin
            if (ok != 0) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                case (what)
                    0:       $error("coverage N=%0d: no-request cycle not reached", n);
                    1:       $error("coverage N=%0d: not every requester was seen alone", n);
                    2:       $error("coverage N=%0d: everyone-requesting cycle not reached", n);
                    3:       $error("coverage N=%0d: held request among changing others not reached", n);
                    4:       $error("coverage N=%0d: longest fair wait (N-1) not reached", n);
                    5:       $error("coverage N=%0d: reset during traffic not reached", n);
                    default: $error("coverage N=%0d: item %0d not reached", n, what);
                endcase
            end
        end
    endtask

    initial begin
        nonce = {(8*64){1'b0}};
        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
            nonce = {(8*64){1'b0}};
        passed    = 0;
        failed    = 0;
        rs        = 1'b0;
        prev_rs   = 1'b0;
        ptr_valid = 1'b0;
        rnd       = 32'd0;
        for (q = 0; q < 16; q = q + 1) waitc[q] = 0;
        for (q = 0; q < 2; q = q + 1) begin
            m_ptr[q]     = 0;
            m_win[q]     = -1;
            cov_none[q]  = 0;
            cov_all[q]   = 0;
            cov_held[q]  = 0;
            cov_maxw[q]  = 0;
            cov_rst[q]   = 0;
            cov_alone[q] = 8'd0;
            prev_r[q]    = 8'd0;
            last_g[q]    = 8'd0;
        end
        rst_n = 1'b0;
        req4  = 4'd0;
        req5  = 5'd0;
        @(negedge clk);

        // 1. Reset, no traffic.
        run_cycle;
        run_cycle;

        // 2. No requests.
        rst_n = 1'b1;
        repeat (3) run_cycle;

        // 3. Each requester alone.
        for (k = 0; k < 5; k = k + 1) begin
            req4 = (k < 4) ? (4'd1 << k) : 4'd0;
            req5 = 5'd1 << k;
            run_cycle;
            run_cycle;
        end

        // 4. Reset, then everyone requesting: strict rotation from 0.
        rst_n = 1'b0;
        req4  = 4'd0;
        req5  = 5'd0;
        run_cycle;
        rst_n = 1'b1;
        req4  = 4'b1111;
        req5  = 5'b11111;
        for (k = 0; k < 20; k = k + 1) begin
            run_cycle;
            if (last_g[0] !== onehot8(k % 4)) begin
                $error("rr_arbiter N=4: rotation step %0d granted %b, expected %b",
                       k, last_g[0], onehot8(k % 4));
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
            if (last_g[1] !== onehot8(k % 5)) begin
                $error("rr_arbiter N=5: rotation step %0d granted %b, expected %b",
                       k, last_g[1], onehot8(k % 5));
                failed = failed + 1;
            end else begin
                passed = passed + 1;
            end
        end

        // 5. Reset, then a held request (top requester) among changing others.
        rst_n = 1'b0;
        req4  = 4'd0;
        req5  = 5'd0;
        run_cycle;
        rst_n = 1'b1;
        for (k = 0; k < 24; k = k + 1) begin
            case (k % 4)
                0:       begin req4 = 4'b1001; req5 = 5'b10001; end
                1:       begin req4 = 4'b1110; req5 = 5'b10110; end
                2:       begin req4 = 4'b1011; req5 = 5'b11011; end
                default: begin req4 = 4'b1101; req5 = 5'b11101; end
            endcase
            run_cycle;
        end

        // 6. Random subsets, drops and raises, with resets during traffic.
        for (k = 0; k < 300; k = k + 1) begin
            rnd = $random;
            case (k % 4)
                0:       begin req4 = rnd[3:0];             req5 = rnd[8:4]; end
                1:       begin req4 = rnd[3:0] & rnd[7:4];  req5 = rnd[12:8] & rnd[17:13]; end
                2:       begin req4 = rnd[3:0] | rnd[7:4];  req5 = rnd[12:8] | rnd[17:13]; end
                default: begin req4 = 4'b1111;              req5 = 5'b11111; end
            endcase
            rst_n = ((k == 120) || (k == 121) || (k == 250)) ? 1'b0 : 1'b1;
            if (!rst_n) begin
                req4 = req4 | 4'b1001;
                req5 = req5 | 5'b10010;
            end
            run_cycle;
        end

        // 7. Drain.
        rst_n = 1'b1;
        req4  = 4'b1111;
        req5  = 5'b11111;
        repeat (6) run_cycle;
        req4 = 4'd0;
        req5 = 5'd0;
        repeat (2) run_cycle;

        // Coverage: every case the interface spec names must be reached.
        for (q = 0; q < 2; q = q + 1) begin
            cov_check(cov_none[q], q + 4, 0);
            cov_check((cov_alone[q] == mask8(q + 4)) ? 1 : 0, q + 4, 1);
            cov_check(cov_all[q], q + 4, 2);
            cov_check(cov_held[q], q + 4, 3);
            cov_check(cov_maxw[q], q + 4, 4);
            cov_check(cov_rst[q], q + 4, 5);
        end

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
